    # Apply pairwise orthogonal projections where markers form a diagonal pair.
    colors=[(v,p[0]) for v,p in pts.items() if p]
    for i,(v,(r,c)) in enumerate(colors):
        for u,(rr,cc) in colors[i+1:]:
