    # its center. Continue the color-6 diagonal down-left from its own marker.
    if p[2]:
        r,c=p[2][0]
        for dc,v in [(-2,2),(-1,5),(0,4),(1,5),(2,2)]:put(r,c+dc,v)
    if p[6]:
        r,c=p[6][0]
        # diagonal 4 trail down-left; ends at boundary, retaining 6 source
        k=1
