    if p[6]:
        r,c=p[6][0]
        put(0,c,6)
        for y in range(1,r):put(y,c,5)
    # 1 extends in direction determined by the paired 2/3 positions
    if p[1]:
        r,c=p[1][0]
        put(r,c+1,5);put(r,c+2,5)
        put(r-1,c+2,1)
