def transform(grid):
    h,w=len(grid),len(grid[0]); g=[row[:] for row in grid]
    p={v:[] for v in range(1,10)}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v:p[v].append((r,c))
    def put(r,c,v):
        if 0<=r<h and 0<=c<w:g[r][c]=v
    if p[1]:
        r,c=p[1][0]; put(r,c+1,5);put(r,c+2,5);put(r-1,c+2,1)
    if p[2]:
        r,c=p[2][0]
        for dc in (-2,-1,0,1,2):put(r,c+dc,2 if abs(dc)==2 else (4 if p[6] and dc==0 else 5))
    if p[6]:
        r,c=p[6][0];put(0,c,6)
        for y in range(1,r):put(y,c,5)
        k=1
        while r+k<h and c-k>=0:put(r+k,c-k,4);k+=1
    if p[3]:
        r,c=p[3][0];put(r+1,c,5);put(r+2,c,5);put(r+3,c,3)
    return g

