def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                points[color] = (r, c)
    def put(r, c, color):
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = color
    if 1 in points:
        r, c = points[1]
        put(r, c + 1, 5); put(r, c + 2, 5); put(r - 1, c + 2, 1)
    if 2 in points:
        r, c = points[2]
        center = c - 2
        for x in range(c - 4, c + 1):
            put(r, x, 2 if x in (c - 4, c) else 5)
        if any(v in points and points[v][1] == center for v in (3, 6)):
            put(r, center, 4)
            k = 1
            while r + k < h and center - k >= 0:
                put(r + k, center - k, 4); k += 1
    if 3 in points:
        r, c = points[3]
        put(r + 1, c, 5); put(r + 2, c, 5); put(r + 3, c, 3)
    if 6 in points:
        r, c = points[6]
        put(0, c, 6)
        for y in range(1, r): put(y, c, 5)
    return out
