    # Color 1 adds a two-cell 5 connector and a copy diagonally up-right.
    if 1 in points:
        r, c = points[1]
        put(r, c + 1, 5)
        put(r, c + 2, 5)
        put(r - 1, c + 2, 1)

    # Color 2 forms a five-cell bar extending left. A marker two columns
    # left of the 2 supplies a 4 midpoint and a down-left diagonal of 4s.
    if 2 in points:
